/** Raised when a component holds a `%` not followed by two hex digits. */
export class UriError extends Error {}

class PercentTruncated extends Error {}

/**
 * Parses a URI reference into its five generic-syntax components. `scheme`,
 * `authority`, `query` and `fragment` are `undefined` when absent (as
 * opposed to present-but-empty); `path` is always a string. `authority`,
 * when present, is `{ userinfo, host, port }` with `userinfo` and `port`
 * following the same present/absent distinction.
 */
export function parseUri(str) {
  let rest = str
  let scheme

  let schemeEnd = -1
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === ':') {
      schemeEnd = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (schemeEnd !== -1) {
    scheme = str.slice(0, schemeEnd)
    rest = str.slice(schemeEnd + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    const afterSlashes = rest.slice(2)
    let end = afterSlashes.length
    for (let i = 0; i < afterSlashes.length; i++) {
      const c = afterSlashes[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = parseAuthority(afterSlashes.slice(0, end))
    rest = afterSlashes.slice(end)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query
  if (rest.startsWith('?')) {
    const hashIdx = rest.indexOf('#')
    const end = hashIdx === -1 ? rest.length : hashIdx
    query = rest.slice(1, end)
    rest = rest.slice(end)
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

function parseAuthority(raw) {
  let userinfo
  let rest = raw
  const atIdx = raw.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = raw.slice(0, atIdx)
    rest = raw.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const colonIdx = rest.indexOf(':', bracketIdx + 1)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
  }

  return { userinfo, host, port }
}

function serialize({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) {
    out += '//'
    if (authority.userinfo !== undefined) out += authority.userinfo + '@'
    out += authority.host
    if (authority.port !== undefined) out += ':' + authority.port
  }
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

function isUnreservedByte(byte) {
  if (byte >= 0x41 && byte <= 0x5a) return true // A-Z
  if (byte >= 0x61 && byte <= 0x7a) return true // a-z
  if (byte >= 0x30 && byte <= 0x39) return true // 0-9
  return byte === 0x2d || byte === 0x2e || byte === 0x5f || byte === 0x7e // - . _ ~
}

function normalizePercent(str) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c !== '%') {
      out += c
      continue
    }
    const h1 = str[i + 1]
    const h2 = str[i + 2]
    if (h1 === undefined || h2 === undefined || !HEX_RE.test(h1) || !HEX_RE.test(h2)) {
      throw new PercentTruncated()
    }
    const byte = parseInt(h1 + h2, 16)
    if (isUnreservedByte(byte)) {
      out += String.fromCharCode(byte)
    } else {
      out += '%' + h1.toUpperCase() + h2.toUpperCase()
    }
    i += 2
  }
  return out
}

function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input.startsWith('/')) {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) {
