 * the normalized URI reference string. Throws UriError when a `%` in any
 * component is not followed by two hex digits, naming whichever of path,
 * userinfo, host, query or fragment carries it (checked in that order).
 */
export function normalize(components) {
  const checks = [
    ['path', components.path],
    ['userinfo', components.authority?.userinfo],
    ['host', components.authority?.host],
    ['query', components.query],
    ['fragment', components.fragment],
  ]
  const normalized = {}
  for (const [name, value] of checks) {
    if (value === undefined) continue
    try {
      normalized[name] = normalizePercent(value)
    } catch {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
  }

