  let authority
  if (components.authority !== undefined) {
    let port = components.authority.port
    if (port !== undefined) {
      const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
      if (port === '' || port === defaultPort) port = undefined
    }
    authority = {
      userinfo: normalized.userinfo,
      host: normalized.host.toLowerCase(),
      port,
    }
  }

  let path = removeDotSegments(normalized.path)
  if (authority !== undefined && path === '') path = '/'

  return serialize({ scheme, authority, path, query: normalized.query, fragment: normalized.fragment })
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolves a parsed reference against a parsed base per RFC 3986 5.2.2
 * strict semantics, and returns the normalized result string.
 */
export function resolve(base, ref) {
  const target = {}

